import numpy as np
from scipy.optimize import least_squares
y=dA_dt; Aa=np.abs(A)
def mk(m):
    def cand(p):
        base = -(p[0] + p[1]/t + p[2]*t + p[3]*np.exp(-t))
        amp = p[4] + p[5]*t + p[6]*t**2
        k = np.exp(p[7] + p[8]*t)
        return base + amp*np.exp(-k*Aa**(-m))
    return cand
for m in [1.0,1.5,2.0,2.5,3.0]:
    cand=mk(m); best=None
    for s in range(25):
        rng=np.random.default_rng(s)
        p0=rng.normal(0,1,9)
        try:
            r=least_squares(lambda p: cand(p)-y, p0, max_nfev=3000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
